CREATE OR REPLACE FUNCTION public.is_published_file(_name text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM public.gallery_photos g WHERE g.path = _name OR g.thumb_path = _name)
      OR EXISTS (SELECT 1 FROM public.packages p WHERE p.visible AND p.cover IS NOT NULL
                 AND _name IN (p.cover->>'path', p.cover->>'thumb_path', p.cover->>'og_path'))
      OR EXISTS (SELECT 1 FROM public.site_content s, jsonb_array_elements(CASE WHEN jsonb_typeof(s.data->'photos') = 'array' THEN s.data->'photos' ELSE '[]'::jsonb END) ph
                 WHERE s.key = 'about' AND _name IN (ph->>'path', ph->>'thumb_path', ph->>'og_path'))
$$;
REVOKE ALL ON FUNCTION public.is_published_file(text) FROM public;
GRANT EXECUTE ON FUNCTION public.is_published_file(text) TO anon, authenticated, service_role;
update site_content set data='{"heroEyebrow": "Watamu · Malindi · Kenya", "heroTitle": "Il Kenya vero, dal mare di Watamu alla savana", "heroText": "Safari in jeep 4x4 con tettuccio apribile ed escursioni via mare e terra, con guida autorizzata in italiano.", "heroNote": "Guida locale in italiano", "introTitle": "Perché scegliere noi", "why": [{"title": "Guida autorizzata in italiano", "text": "Guida autorizzata che parla italiano e autista professionale per tutto il viaggio."}, {"title": "Jeep 4x4 con tettuccio apribile", "text": "Per osservare e fotografare gli animali durante i game drive."}, {"title": "Ingressi e acqua inclusi", "text": "Ingressi ai parchi e acqua durante i game drive sono compresi."}, {"title": "Assicurazione safari completa", "text": "Copertura con veicolo sostitutivo e soccorso."}, {"title": "All-inclusive nei lodge", "text": "Pensione all-inclusive nei lodge (bevande ai pasti escluse), con partenza dal resort a Watamu per i safari brevi."}, {"title": "Su misura su WhatsApp", "text": "Pacchetti costruiti su misura, scrivendo direttamente su WhatsApp."}], "featuredTitle": "Safari in evidenza", "featuredIntro": "Dalla terra rossa dello Tsavo alle pianure del Masai Mara.", "seaEyebrow": "Mare e terra", "seaTitle": "Oltre la savana", "seaText": "Atolli, mangrovie, rovine e tramonti: scopri l’anima della costa keniota.", "footerText": "Safari ed escursioni in Kenya, con base a Watamu e Malindi."}'::jsonb, updated_at=now() where key='home';
update packages set itinerary=jsonb_set(itinerary,'{1}',to_jsonb('Colazione alle 5:30 e partenza alle 6:00. Game drive del mattino uscendo dal parco (uscita verso le 9:00-9:30), breve sosta al fiume Galana per vedere i coccodrilli, poi rientro diretto a Watamu verso le 12:00. Il pranzo non è incluso: si pranza al proprio resort.'::text)) where slug='tsavo-est-2-giorni';
update packages set itinerary=jsonb_set(itinerary,'{3}',to_jsonb('Colazione alle 6:00 e solo trasferimento ad Amboseli, senza game drive al mattino. Pranzo, safari pomeridiano e pernottamento.'::text)) where slug in ('mara-nakuru-amboseli-5-giorni','grande-kenya-6-giorni','kenya-completo-7-giorni');
update site_content set data=data || '{"meTitle": "Chi sono", "me": "Mi chiamo Africano e lavoro con ECO TOURS AND SAFARI''S, sulla costa di Watamu e Malindi. Ho quattro anni di esperienza e, prima di questa avventura, ho collaborato con altre due aziende: da lì ho imparato quanto contano l''organizzazione e i dettagli, dagli orari di partenza ai game drive nei momenti migliori della giornata.\n\nOgni safari e ogni escursione si possono adattare alle tue esigenze: durata, parchi e tappe li decidiamo insieme su WhatsApp. Faremo di tutto perché la tua vacanza sia indimenticabile, tra la savana e il mare del Kenya.\n\nTi aspetto. Benvenuto!", "photos": [], "license": {"text": "", "number": "", "expires": ""}}'::jsonb, updated_at=now() where key='about';
insert into site_content(key,data) values('owner','{"name": "ECO TOURS AND SAFARI''S (Africano)", "address": "", "email": "eazyafricanah@gmail.com", "phone": "+254742161072", "license": "", "retention": "", "transfers": "", "law": "Legge del Kenya, fatte salve le tutele inderogabili dei consumatori."}'::jsonb) on conflict (key) do update set data=site_content.data || excluded.data, updated_at=now();